// Generated by AI
using UnityEngine;
using UnityEngine.UI;

public class UIButtonHighlight : MonoBehaviour
{
    [Header("Highlight Settings")]
    [SerializeField] private Color highlightColor = new Color(0f, 0.89f, 1f);
    private Image buttonImage;
    private Color originalColor;

    private void Start()
    {
        // Cache the button image and preserve its initial color.
        buttonImage = GetComponent<Image>();

        if (buttonImage != null)
        {
            originalColor = buttonImage.color;
        }
    }

    // Applies the configured highlight color to the button.
    public void StartHighlight()
    {
        if (buttonImage != null)
        {
            buttonImage.color = highlightColor;
        }
    }

    // Restores the button's original color.
    public void StopHighlight()
    {
        if (buttonImage != null)
        {
            buttonImage.color = originalColor;
        }
    }
}